using System; using System.Collections.Generic; using System.Text.Json; namespace Test { public class OcrField { public string Name { get; set; } } public record OcrResult { public bool Success { get; init; } public string ExtractedText { get; init; } public Dictionary<string, OcrField> Fields { get; init; } = new Dictionary<string, OcrField>(); } class Program { static void Main() { var o = new OcrResult { Success = true, ExtractedText = "test", Fields = new Dictionary<string, OcrField> { { "campo1", new OcrField { Name = "campo1" } } } }; var json = JsonSerializer.Serialize(o, new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }); Console.WriteLine(json); } } }
